/* From Uiverse.io by andrew-demchenk0 - Tags: animation, card, hover, light, product, project, hover effect */
.__UIV_SCOPE__ .card {
  --main-color: #323232;
  --sub-color: #5b5b5b;
  --bg-color: #c7c7c7;
  --accent-color: #242C88;
  position: relative;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  width: 270px;
  padding: 25px;
  border-radius: 25px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  background-color: var(--bg-color);
  transition: all 0.2s;
  cursor: pointer;
  box-shadow: 0px 0px 5px -1.5px #000;
}

.__UIV_SCOPE__ .card::before {
  content: '';
  width: 99%;
  height: 99%;
  background: var(--sub-color);
  position: absolute;
  z-index: -1;
  top: 1px;
  left: 1px;
  border-radius: 25px;
  transition: all 0.3s;
}

.__UIV_SCOPE__ .card__wrapper {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
}

.__UIV_SCOPE__ .card__img {
  width: 100%;
}

.__UIV_SCOPE__ .card__title {
  color: var(--main-color);
  font-weight: 900;
  font-size: 25px;
}

.__UIV_SCOPE__ .card__subtitle {
  color: var(--sub-color);
  font-weight: 600;
  font-size: 20px;
}

.__UIV_SCOPE__ .card__icon {
  width: 40px;
  height: 40px;
  transform: rotate(-45deg);
  transition: all 0.3s;
}

.__UIV_SCOPE__ .card__icon svg {
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .card__icon g {
  fill: var(--main-color);
}

.__UIV_SCOPE__ .card__icon circle, .__UIV_SCOPE__ polyline, .__UIV_SCOPE__ line {
  stroke: var(--main-color);
}

.__UIV_SCOPE__ .card:hover .card__icon {
  transform: rotate(0);
}

.__UIV_SCOPE__ .card:hover .card__icon circle, .__UIV_SCOPE__ .card:hover .card__icon polyline, .__UIV_SCOPE__ .card:hover .card__icon line {
  stroke: var(--accent-color);
}

.__UIV_SCOPE__ .card:hover .card__icon g {
  fill: var(--accent-color);
}

.__UIV_SCOPE__ .card:hover {
  box-shadow: 0px 0px 20px -5px #000;
}

.__UIV_SCOPE__ .card:hover::before {
  transform: rotate(10deg);
  box-shadow: 0px 0px 20px -5px #000;
}

/* remove svg from class ="card__img" and last styles below css code before use */
.__UIV_SCOPE__ .st1 {
  fill: #fff
}

.__UIV_SCOPE__ .st2 {
  fill: none;
  stroke: #242c88;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-miterlimit: 10
}

.__UIV_SCOPE__ .st7 {
  fill: #589fff
}

.__UIV_SCOPE__ .st9 {
  fill: #bc8d66
}

.__UIV_SCOPE__ .st15,.__UIV_SCOPE__ .st16 {
  opacity: .4;
  fill: #242c88
}

.__UIV_SCOPE__ .st16 {
  opacity: .2
}

.__UIV_SCOPE__ .st18 {
  fill: #ffc408
}

.__UIV_SCOPE__ .st53 {
  fill: none;
  stroke: #242c88;
  stroke-width: 1.848;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-miterlimit: 10
}
